<?php
require_once __DIR__ . '/include/config.php';
require_once __DIR__ . '/../include/clinical.php';
hms_start_session();
hms_require_role('doctor');
$doctor = (int) $_SESSION['id'];
$ready = hms_stage6_ready($con);
$error = '';
if ($ready && $_SERVER['REQUEST_METHOD'] === 'POST') {
    hms_verify_csrf();
    try {
        $patient = (int) ($_POST['patient_user_id'] ?? 0);
        $names = $_POST['medicine_name'] ?? [];
        $dosages = $_POST['dosage'] ?? [];
        $frequencies = $_POST['frequency'] ?? [];
        $durations = $_POST['duration'] ?? [];
        $instructions = $_POST['instructions'] ?? [];
        if (!hms_doctor_patient_allowed($con, $doctor, $patient) || !is_array($names) || count($names) < 1 || count($names) > 12) throw new InvalidArgumentException('Choose an authorized patient and add one to twelve medicines.');
        $con->begin_transaction();
        hms_db_query($con, 'INSERT INTO prescription_headers(patient_user_id,doctor_id,issue_date,clinical_notes) VALUES(?,?,?,?)', [$patient, $doctor, date('Y-m-d'), hms_post_string('clinical_notes', 4000) ?: null]);
        $prescriptionId = (int) $con->insert_id;
        foreach ($names as $key => $name) {
            $name = trim((string) $name); $dosage = trim((string) ($dosages[$key] ?? '')); $frequency = trim((string) ($frequencies[$key] ?? '')); $duration = trim((string) ($durations[$key] ?? '')); $instruction = trim((string) ($instructions[$key] ?? ''));
            if ($name === '' || $dosage === '' || $frequency === '' || $duration === '' || strlen($name) > 180 || strlen($dosage) > 100 || strlen($frequency) > 100 || strlen($duration) > 100 || strlen($instruction) > 1000) throw new InvalidArgumentException('Complete every medicine direction.');
            hms_db_query($con, 'INSERT INTO prescription_items(prescription_id,medicine_name,dosage,frequency,duration,instructions) VALUES(?,?,?,?,?,?)', [$prescriptionId, $name, $dosage, $frequency, $duration, $instruction ?: null]);
        }
        $con->commit(); header('Location: prescriptions.php?created=' . $prescriptionId); exit;
    } catch (Throwable $exception) {
        if ($con->errno) $con->rollback();
        error_log('HMS prescription: ' . $exception->getMessage());
        $error = $exception instanceof InvalidArgumentException ? $exception->getMessage() : 'Prescription could not be saved.';
    }
}
$patients = $ready ? hms_clinical_patients($con, $doctor) : null;
$rows = $ready ? hms_db_query($con, 'SELECT h.id,h.issue_date,u.fullName patient,COUNT(i.id) medicines FROM prescription_headers h JOIN users u ON u.id=h.patient_user_id JOIN prescription_items i ON i.prescription_id=h.id WHERE h.doctor_id=? GROUP BY h.id ORDER BY h.id DESC', [$doctor]) : null;
?>
