<style>.rx-workspace{padding-bottom:48px}.rx-heading{margin:0 0 20px}.rx-heading h1{margin:0;font-size:27px;font-weight:700}.rx-heading p{margin:5px 0 0;color:var(--mt-muted);font-size:12px}.rx-layout{display:grid;grid-template-columns:minmax(0,1fr) 350px;gap:18px;align-items:start}.rx-panel{min-width:0;background:#fff;border:1px solid var(--mt-border);border-radius:12px;box-shadow:0 4px 16px rgba(18,48,74,.04);overflow:hidden}.rx-panel-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:17px 20px;border-bottom:1px solid var(--mt-border)}.rx-panel-head h2{margin:0;font-size:16px;font-weight:700}.rx-panel-head span{color:var(--mt-muted);font-size:11px}.rx-table{min-width:560px;margin:0!important;border:0!important;border-radius:0!important}.rx-table>thead>tr>th{padding:12px 14px!important}.rx-table>tbody>tr>td{padding:14px!important;vertical-align:middle!important}.rx-patient{font-weight:700;color:var(--mt-text)}.rx-view{display:inline-flex;align-items:center;gap:5px;color:var(--mt-primary);font-size:11px;font-weight:700;white-space:nowrap}.rx-form{padding:20px}.rx-form h2{margin:0 0 5px;font-size:18px}.rx-form>p{margin:0 0 17px;color:var(--mt-muted);font-size:11px}.rx-form label{display:block;margin:0 0 5px;color:#40566b;font-size:11px;font-weight:650}.rx-form .form-control{margin:0 0 12px;font-size:12px}.rx-form textarea{min-height:88px;resize:vertical}.rx-medicine{margin:11px 0;padding:13px;border:1px solid #dfeaf2;border-radius:10px;background:#f9fbfd}.rx-medicine-title{display:block;margin:0 0 9px;color:var(--mt-primary);font-size:10px;font-weight:800;letter-spacing:.06em;text-transform:uppercase}.rx-medicine .form-control{margin-bottom:8px}.rx-actions{display:flex;gap:9px;margin-top:15px}.rx-actions .btn{min-height:42px;padding:0 14px}.rx-actions .btn-primary{flex:1}.rx-empty{padding:40px 22px;text-align:center;color:var(--mt-muted)}.rx-empty i{display:grid;width:42px;height:42px;place-items:center;margin:0 auto 11px;border-radius:10px;background:#eaf3fb;color:var(--mt-primary);font-size:18px}.rx-empty strong{display:block;color:var(--mt-text);font-size:13px}.rx-empty span{display:block;margin-top:4px;font-size:11px}@media(max-width:991px){.rx-layout{grid-template-columns:1fr}.rx-form{max-width:none}}@media(max-width:767px){.rx-panel-head{align-items:flex-start;flex-direction:column;gap:4px}.rx-table{min-width:560px}.rx-actions{align-items:stretch;flex-direction:column}.rx-actions .btn{width:100%}}</style></head>
<body><div id="app"><?php include 'include/sidebar.php'; ?><div class="app-content"><?php include 'include/header.php'; ?><main class="main-content"><div class="wrap-content container rx-workspace"><section id="page-title"><h1 class="mainTitle">Prescriptions</h1><ol class="breadcrumb"><li><span>Doctor portal</span></li><li class="active"><span>Prescriptions</span></li></ol></section><div class="rx-heading"><h1>Prescription management</h1><p>Create prescriptions for your authorized patients and review issued treatment plans.</p></div>
<?php if (!$ready): ?><div class="alert alert-warning"><?= hms_h(hms_clinical_notice()) ?></div><?php endif; ?><?php if ($error !== ''): ?><div class="alert alert-danger"><?= hms_h($error) ?></div><?php endif; ?><?php if (isset($_GET['created'])): ?><div class="alert alert-success">Prescription saved. <a href="../prescription-details.php?id=<?= hms_h((int) $_GET['created']) ?>">View or print it</a>.</div><?php endif; ?>
<div class="rx-layout"><section class="rx-panel"><header class="rx-panel-head"><h2>Recent prescriptions</h2><span><?= $rows ? (int) $rows->num_rows : 0 ?> record<?= $rows && $rows->num_rows === 1 ? '' : 's' ?></span></header><?php if ($rows && $rows->num_rows > 0): ?><div class="table-responsive"><table class="table rx-table"><thead><tr><th>Date</th><th>Patient</th><th>Medicines</th><th>Document</th></tr></thead><tbody><?php while ($row = $rows->fetch_assoc()): ?><tr><td><?= hms_h($row['issue_date']) ?></td><td><span class="rx-patient"><?= hms_h($row['patient']) ?></span></td><td><?= hms_h($row['medicines']) ?></td><td><a class="rx-view" href="../prescription-details.php?id=<?= hms_h($row['id']) ?>"><i class="fa fa-file-text-o"></i> View / print</a></td></tr><?php endwhile; ?></tbody></table></div><?php else: ?><div class="rx-empty"><i class="ti-clipboard"></i><strong>No prescriptions yet</strong><span>Issued prescriptions will appear here.</span></div><?php endif; ?></section>
<?php if ($ready): ?><aside class="rx-panel"><form class="rx-form" method="post"><?= hms_csrf_field() ?><h2>New prescription</h2><p>Only patients linked to your care can be selected.</p><label for="rx-patient">Patient</label><select id="rx-patient" name="patient_user_id" class="form-control" required><option value="">Choose patient</option><?php while ($patient = $patients->fetch_assoc()): ?><option value="<?= hms_h($patient['id']) ?>"><?= hms_h($patient['fullName']) ?></option><?php endwhile; ?></select><label for="rx-notes">Clinical note <span class="text-muted">optional</span></label><textarea id="rx-notes" class="form-control" name="clinical_notes" maxlength="4000" placeholder="Relevant diagnosis, advice, or follow-up notes"></textarea><div id="meds"><div class="rx-medicine"><span class="rx-medicine-title">Medicine 1</span><input class="form-control" name="medicine_name[]" maxlength="180" placeholder="Medicine name" required><input class="form-control" name="dosage[]" maxlength="100" placeholder="Dosage" required><input class="form-control" name="frequency[]" maxlength="100" placeholder="Frequency" required><input class="form-control" name="duration[]" maxlength="100" placeholder="Duration" required><input class="form-control" name="instructions[]" maxlength="1000" placeholder="Instructions (optional)"></div></div><div class="rx-actions"><button type="button" class="btn btn-default" onclick="addMed()"><i class="fa fa-plus"></i> Add medicine</button><button class="btn btn-primary" type="submit"><i class="fa fa-check"></i> Save prescription</button></div></form></aside><?php endif; ?></div></div></main><?php include 'include/footer.php'; ?></div></div>
<script src="vendor/jquery/jquery.min.js"></script><script src="vendor/bootstrap/js/bootstrap.min.js"></script><script src="vendor/modernizr/modernizr.js"></script><script src="vendor/jquery-cookie/jquery.cookie.js"></script><script src="vendor/perfect-scrollbar/perfect-scrollbar.min.js"></script><script src="vendor/switchery/switchery.min.js"></script><script src="assets/js/main.js"></script><script>function addMed(){var medicines=document.querySelectorAll('.rx-medicine');if(medicines.length>=12)return;var medicine=medicines[0].cloneNode(true);medicine.querySelectorAll('input').forEach(function(input){input.value='';});medicine.querySelector('.rx-medicine-title').textContent='Medicine '+(medicines.length+1);document.querySelector('#meds').appendChild(medicine)}jQuery(function(){Main.init();});</script></body></html>
